create extension if not exists pgcrypto;
create table public.groups(id uuid primary key default gen_random_uuid(), name text not null, sport text not null default 'Cầu lông', created_by uuid not null references auth.users, created_at timestamptz not null default now());
create table public.group_members(id uuid primary key default gen_random_uuid(), group_id uuid not null references public.groups, user_id uuid references auth.users, display_name text not null, aliases text[] not null default '{}', role text not null default 'member' check(role in ('admin','member')), status text not null default 'active' check(status in ('active','removed')), created_at timestamptz not null default now(), unique(group_id,user_id));
create table public.sessions(id uuid primary key default gen_random_uuid(), group_id uuid not null references public.groups, title text not null, venue text not null, starts_at timestamptz not null, commit_deadline timestamptz not null, status text not null default 'planned' check(status in ('planned','played','settled','cancelled')), collector_member_id uuid references public.group_members, created_by uuid not null references auth.users, note text, revision bigint not null default 0, settled_at timestamptz, created_at timestamptz not null default now());
create table public.session_attendees(session_id uuid references public.sessions, member_id uuid references public.group_members, rsvp text not null default 'none' check(rsvp in ('none','going','maybe','not_going')), committed_at timestamptz, weight numeric not null default 1 check(weight>0), removed_at timestamptz, created_at timestamptz not null default now(), primary key(session_id,member_id));
create table public.expenses(id uuid primary key default gen_random_uuid(),session_id uuid not null references public.sessions,title text not null,kind text not null default 'extra' check(kind in ('court','extra')),amount bigint not null,paid_by uuid not null references public.group_members,status text not null default 'active' check(status in ('active','proposed','rejected','deleted')),created_at timestamptz not null default now());
create table public.expense_allocations(expense_id uuid references public.expenses,member_id uuid references public.group_members,share_amount bigint not null,created_at timestamptz not null default now(),primary key(expense_id,member_id));
create table public.settlements(id uuid primary key default gen_random_uuid(),session_id uuid not null references public.sessions,from_member uuid not null references public.group_members,to_member uuid not null references public.group_members,amount bigint not null check(amount>0),ref_code text not null unique,status text not null default 'pending' check(status in ('pending','marked_paid','confirmed','cancelled')),kind text not null default 'original',marked_paid_at timestamptz,confirmed_at timestamptz,created_at timestamptz not null default now(),check(from_member<>to_member));
create table public.audit_log(id uuid primary key default gen_random_uuid(),group_id uuid not null references public.groups,session_id uuid references public.sessions,actor_id uuid references auth.users,action text not null,payload jsonb not null default '{}',created_at timestamptz not null default now());
create table public.attendance_events(id uuid primary key default gen_random_uuid(),session_id uuid not null references public.sessions,member_id uuid not null references public.group_members,actor_id uuid not null references auth.users,action text not null,created_at timestamptz not null default now());
create or replace function public.is_member(g uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.group_members where group_id=g and user_id=auth.uid() and status='active')$$;
create function public.immutable_log() returns trigger language plpgsql set search_path='' as $$begin raise exception 'Bản ghi lịch sử là bất biến';end$$;
create trigger immutable_audit before update or delete on public.audit_log for each row execute function public.immutable_log();
create trigger immutable_attendance before update or delete on public.attendance_events for each row execute function public.immutable_log();
create function public.protect_confirmed() returns trigger language plpgsql set search_path='' as $$begin if old.status='confirmed' then raise exception 'Khoản đã xác nhận là bất biến';end if;return new;end$$;
create trigger confirmed_immutable before update or delete on public.settlements for each row execute function public.protect_confirmed();
alter table public.groups enable row level security;
alter table public.group_members enable row level security;
alter table public.sessions enable row level security;
alter table public.session_attendees enable row level security;
alter table public.expenses enable row level security;
alter table public.expense_allocations enable row level security;
alter table public.settlements enable row level security;
alter table public.audit_log enable row level security;
alter table public.attendance_events enable row level security;
create policy groups_read on public.groups for select to authenticated using(public.is_member(id));
create policy members_read on public.group_members for select to authenticated using(public.is_member(group_id));
create policy sessions_read on public.sessions for select to authenticated using(public.is_member(group_id));
create policy attendees_read on public.session_attendees for select to authenticated using(exists(select 1 from public.sessions s where s.id=session_id and public.is_member(s.group_id)));
create policy expenses_read on public.expenses for select to authenticated using(exists(select 1 from public.sessions s where s.id=session_id and public.is_member(s.group_id)));
create policy allocations_read on public.expense_allocations for select to authenticated using(exists(select 1 from public.expenses e join public.sessions s on s.id=e.session_id where e.id=expense_id and public.is_member(s.group_id)));
create policy settlements_read on public.settlements for select to authenticated using(exists(select 1 from public.sessions s where s.id=session_id and public.is_member(s.group_id)));
create policy audit_read on public.audit_log for select to authenticated using(public.is_member(group_id));
create policy attendance_read on public.attendance_events for select to authenticated using(exists(select 1 from public.sessions s where s.id=session_id and public.is_member(s.group_id)));
revoke insert,update,delete on public.groups,public.group_members,public.sessions,public.session_attendees,public.expenses,public.expense_allocations,public.settlements,public.audit_log,public.attendance_events from anon,authenticated;
create function public.payment_action(target uuid,operation text) returns void language plpgsql security definer set search_path='' as $$
declare pay public.settlements; sess public.sessions; actor uuid;
begin
 select s.* into sess from public.sessions s join public.settlements p on p.session_id=s.id where p.id=target for update of s;
 if not found or not public.is_member(sess.group_id) then raise exception 'Không có quyền';end if;
 select * into pay from public.settlements where id=target for update;
 select id into actor from public.group_members where group_id=sess.group_id and user_id=auth.uid() and status='active';
 if operation='mark' and actor=pay.from_member and pay.status='pending' then update public.settlements set status='marked_paid',marked_paid_at=now() where id=target;
 elsif operation='confirm' and actor=pay.to_member and pay.status in ('pending','marked_paid') then update public.settlements set status='confirmed',confirmed_at=now() where id=target;
 else raise exception 'Thao tác không được phép hoặc khoản đã thay đổi';end if;
 insert into public.audit_log(group_id,session_id,actor_id,action,payload) values(sess.group_id,sess.id,auth.uid(),operation,jsonb_build_object('settlement_id',target));
 if not exists(select 1 from public.settlements where session_id=sess.id and status in ('pending','marked_paid')) then update public.sessions set status='settled',settled_at=now(),revision=revision+1 where id=sess.id;end if;
end$$;
revoke execute on all functions in schema public from public,anon;
grant execute on function public.is_member(uuid),public.payment_action(uuid,text) to authenticated;
